@namespace sv_90e211b5483b4f5dbd8377eaf142353a.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLower()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeft" disabled="@IsMoving">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRight" disabled="@IsMoving">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback MoveLeft { get; set; }
    [Parameter] public EventCallback MoveRight { get; set; }

    private bool IsMoving;

    private async System.Threading.Tasks.Task OnMoveLeft()
    {
        IsMoving = true;
        await MoveLeft.InvokeAsync();
        IsMoving = false;
    }

    private async System.Threading.Tasks.Task OnMoveRight()
    {
        IsMoving = true;
        await MoveRight.InvokeAsync();
        IsMoving = false;
    }
}

@namespace sv_90e211b5483b4f5dbd8377eaf142353a.Components.Pages.Board

@if (!IsVisible)
{
    <button class="btn-add-task" @onclick="Show">+ Add Task</button>
}
else
{
    <div class="add-task-form">
        <input type="text" placeholder="Title" @bind="Title" />
        <input type="text" placeholder="Assignee" @bind="Assignee" />
        <select @bind="Priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
        <input type="date" @bind="DueDate" />
        <div class="form-actions">
            <button class="btn-save" @onclick="Save" disabled="@IsSaving">Save</button>
            <button class="btn-cancel" @onclick="Cancel">Cancel</button>
        </div>
    </div>
}

@code {
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private bool IsVisible;
    private bool IsSaving;
    private string Title = "";
    private string Assignee = "";
    private string Priority = "Medium";
    private DateTime DueDate = DateTime.Today.AddDays(7);

    private void Show() => IsVisible = true;

    private void Cancel()
    {
        IsVisible = false;
        ResetForm();
    }

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(Title)) return;

        IsSaving = true;
        await OnTaskCreated.InvokeAsync((Title, Assignee, Priority, DueDate));
        IsSaving = false;
        IsVisible = false;
        ResetForm();
    }

    private void ResetForm()
    {
        Title = "";
        Assignee = "";
        Priority = "Medium";
        DueDate = DateTime.Today.AddDays(7);
    }
}

@namespace sv_90e211b5483b4f5dbd8377eaf142353a.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      MoveLeft="() => OnMoveLeft.InvokeAsync(task.Id)"
                      MoveRight="() => OnMoveRight.InvokeAsync(task.Id)" />
        }
    </div>
    <div class="column-footer">
        <AddTaskForm OnTaskCreated="OnTaskCreated" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }
}

@namespace sv_90e211b5483b4f5dbd8377eaf142353a.Components.Pages.Board

<div class="board-stats">
    <div class="stat-item">
        <span class="stat-label">Total</span>
        <span class="stat-value">@Total</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">To Do</span>
        <span class="stat-value">@TodoCount</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">In Progress</span>
        <span class="stat-value">@InProgressCount</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">Done</span>
        <span class="stat-value">@DoneCount</span>
    </div>
    <div class="stat-item stat-overdue">
        <span class="stat-label">Overdue</span>
        <span class="stat-value">@OverdueCount</span>
    </div>
</div>

@code {
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();

    private int Total => Tasks.Count;
    private int TodoCount => Tasks.Count(t => t.Status == "To Do");
    private int InProgressCount => Tasks.Count(t => t.Status == "In Progress");
    private int DoneCount => Tasks.Count(t => t.Status == "Done");
    private int OverdueCount => Tasks.Count(t => t.DueDate < DateTime.Today);
}

@namespace sv_90e211b5483b4f5dbd8377eaf142353a.Components.Pages.Board

<div class="task-search-bar">
    <input type="text" placeholder="Search tasks by title..." value="@SearchText"
           @oninput="OnInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task OnInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTextChanged.InvokeAsync(value);
    }
}

