 @if (isLoading)
 {
     <p class="loading-message">Loading tasks...</p>
 }
 else if (errorMessage is not null)
 {
     <div class="error-message">
         <p>@errorMessage</p>
         <button @onclick="LoadTasks">Retry</button>
     </div>
 }
 else
 {
     <BoardStats Tasks="allTasks" />

     <TaskSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

     <div class="kanban-board">
         <KanbanColumn ColumnName="@StatusTodo"
                       Tasks="@GetTasksForStatus(StatusTodo)"
                       ShowMoveLeft="false"
                       ShowMoveRight="true"
                       OnMoveRight="@((int id) => MoveTask(id, StatusInProgress))"
                       OnTaskCreated="@(t => CreateTask(t, StatusTodo))" />

         <KanbanColumn ColumnName="@StatusInProgress"
                       Tasks="@GetTasksForStatus(StatusInProgress)"
                       ShowMoveLeft="true"
                       ShowMoveRight="true"
                       OnMoveLeft="@((int id) => MoveTask(id, StatusTodo))"
                       OnMoveRight="@((int id) => MoveTask(id, StatusDone))"
                       OnTaskCreated="@(t => CreateTask(t, StatusInProgress))" />

         <KanbanColumn ColumnName="@StatusDone"
                       Tasks="@GetTasksForStatus(StatusDone)"
                       ShowMoveLeft="true"
                       ShowMoveRight="false"
                       OnMoveLeft="@((int id) => MoveTask(id, StatusInProgress))"
                       OnTaskCreated="@(t => CreateTask(t, StatusDone))" />
     </div>
 }

 @code {
     private const string StatusTodo = "To Do";
     private const string StatusInProgress = "In Progress";
     private const string StatusDone = "Done";

     private List<TaskItem> allTasks = new();
     private string searchText = "";
     private bool isLoading = true;
     private string? errorMessage;

     protected override async Task OnInitializedAsync()
     {
         await LoadTasks();
     }

     private async Task LoadTasks()
     {
         try
         {
             isLoading = true;
             errorMessage = null;
             allTasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load tasks: {ex.Message}";
         }
         finally
         {
             isLoading = false;
         }
     }

     private void OnSearchChanged(string text)
     {
         searchText = text;
     }

     private List<TaskItem> GetTasksForStatus(string status)
     {
         var tasks = allTasks.Where(t => t.Status == status);

         if (!string.IsNullOrWhiteSpace(searchText))
         {
             tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
         }

         return tasks.ToList();
     }

     private async Task MoveTask(int taskId, string newStatus)
     {
         try
         {
             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
             var task = allTasks.First(t => t.Id == taskId);
             var index = allTasks.IndexOf(task);
             allTasks[index] = task with { Status = newStatus };
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to move task: {ex.Message}";
         }
     }

     private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) form, string status)
     {
         try
         {
             var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
             allTasks.Add(newTask with { Status = status });
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to create task: {ex.Message}";
         }
     }
 }
